 "content": "from collections import Counter
from fractions import Fraction

def _best_periodic(indices):
    """Longest arithmetic progression with at least two entries and gap >= 3."""
    indices = sorted(set(indices))
    best = []
    for a in range(len(indices)):
        for b in range(a + 1, len(indices)):
            step = indices[b] - indices[a]
            if step < 3:
                continue
            seq = [indices[a]]
            nxt = indices[a] + step
            present = set(indices)
            while nxt in present:
                seq.append(nxt)
                nxt += step
            if (len(seq), step) > (len(best), best[1] - best[0] if len(best) > 1 else 0):
                best = seq
    return best

def _find_row_lines(grid):
    h, w = len(grid), len(grid[0])
    candidates = {}
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if count >= 0.65 * w:
            candidates.setdefault(color, []).append(r)
    best_color, best_seq = None, []
    for color, inds in candidates.items():
        seq = _best_periodic(inds)
        if len(seq) > len(best_seq):
            best_color, best_seq = color, seq
    if best_color is None:
        return [], None
    # Include all rows of the separator color that lie in the regular span.
    step = best_seq[1] - best_seq[0]
    lines = [r for r in best_seq if Counter(grid[r]).most_common(1)[0][0] == best_color]
    return lines, best_color

def transform(grid):
    h, w = len(grid), len(grid[0])
    all_rs, sep_color = _find_row_lines(grid)
    if len(all_rs) < 2:
        return []
    ordinary = [r for r in range(h) if r not in all_rs]
    col_candidates = [c for c in range(w)
                      if ordinary and sum(grid[r][c] == sep_color for r in ordinary) >= 0.75 * len(ordinary)]
    cs = _best_periodic(col_candidates)
    if len(cs) < 2:
        return []
    # Cell background is the most frequent color away from detected grid lines.
    interior = [grid[r][c] for r in ordinary for c in range(w) if c not in cs]
    fill = Counter(interior).most_common(1)[0][0] if interior else Counter(v for row in grid for v in row).most_common(1)[0][0]
    active_rs = [r for r in all_rs if any(grid[r][c] != sep_color for c in cs)]
    bands = []
    for i in range(len(active_rs) - 1):
        outrow = []
        marked = False
        for j in range(len(cs) - 1):
            corners = [grid[active_rs[i]][cs[j]], grid[active_rs[i]][cs[j+1]],
                       grid[active_rs[i+1]][cs[j]], grid[active_rs[i+1]][cs[j+1]]]
            value = corners[0] if corners.count(corners[0]) == 4 and corners[0] != sep_color else fill
            outrow.append(value)
            marked |= value != fill
        if marked:
            bands.append(outrow)
    return bands
